* { box-sizing: border-box; margin: 0px; padding: 0px; }body { color: rgb(17, 17, 17); -webkit-font-smoothing: antialiased; background: rgb(255, 255, 255); padding-top: 40px; font-family: "Open Sans", sans-serif; font-size: 14px; line-height: 1.5; }a { color: inherit; text-decoration: none; }ul { list-style: none; }.hidden { display: none !important; }.container { max-width: 1600px; margin: 0px auto; padding: 0px 30px; }[class*=" main-icon-"], [class^="main-icon-"] { font-variant: normal; text-transform: none; -webkit-font-smoothing: antialiased; font-style: normal; font-weight: 400; line-height: 1; font-family: main-icon !important; }.site-header { background: rgb(255, 255, 255); }.header-main-row { border-bottom: 1px solid rgb(238, 238, 238); padding: 25px 0px; }.header-main-inner { justify-content: flex-end; align-items: center; min-height: 40px; display: flex; position: relative; }.header-left-spacer { flex: 1 1 0%; }.site-logo-center { position: absolute; left: 50%; transform: translate(-50%); }.site-logo-center .logo-text { color: rgb(17, 17, 17); letter-spacing: -0.5px; font-family: Spartan, sans-serif; font-size: 32px; font-weight: 700; }.site-logo-center .logo-i { display: inline-block; position: relative; }.site-logo-center .logo-i .leaf { font-size: 14px; line-height: 1; position: absolute; top: -14px; left: 50%; transform: translate(-50%); }.header-controls { align-items: center; gap: 25px; margin-left: auto; display: flex; }.control-item { color: rgb(17, 17, 17); cursor: pointer; align-items: center; gap: 6px; transition: color 0.2s; display: flex; }.control-item:hover { color: rgb(136, 189, 67); }.control-item [class^="main-icon-"] { color: rgb(17, 17, 17); font-size: 22px; }.control-item .count-badge { color: rgb(255, 255, 255); background: rgb(136, 189, 67); border-radius: 50%; justify-content: center; align-items: center; min-width: 20px; height: 20px; font-family: Spartan, sans-serif; font-size: 11px; font-weight: 600; display: flex; }.control-item