adding: 0px 20px; font-size: 28px; line-height: 1; transition: color 0.2s; }.search-close-btn:hover { color: rgb(51, 51, 51); }.site-header { position: relative; }.hero-slider { width: 100%; height: 700px; position: relative; overflow: hidden; }.hero-slide { opacity: 0; visibility: hidden; width: 100%; height: 100%; transition: opacity 0.8s, visibility 0.8s; position: absolute; top: 0px; left: 0px; }.hero-slide.active { opacity: 1; visibility: visible; }.slide-bg { z-index: 1; width: 100%; height: 100%; position: absolute; top: 0px; left: 0px; }.slide-content { z-index: 2; justify-content: flex-start; align-items: center; height: 100%; display: flex; position: relative; }.slide-content .container { justify-content: flex-start; align-items: center; width: 100%; display: flex; }.slide-text-box { text-align: left; max-width: 550px; margin-left: 80px; padding: 0px; }.slide-subtitle { letter-spacing: 4px; text-transform: uppercase; color: rgb(0, 0, 0); margin-bottom: 15px; font-family: Spartan, sans-serif; font-size: 14px; font-weight: 700; display: block; }.slide-title { color: rgb(0, 0, 0); text-align: left; margin-bottom: 25px; font-family: Spartan, sans-serif; font-size: 70px; font-weight: 700; line-height: 1.1; }.slide-title.script-title { font-family: Reingttoon, "Dancing Script", cursive; font-size: 90px; font-weight: 400; line-height: 1; }.slide-desc { color: rgb(0, 0, 0); text-align: left; max-width: 500px; margin-bottom: 30px; font-family: "Open Sans", sans-serif; font-size: 16px; line-height: 1.7; }.slide-btn { color: rgb(255, 255, 255); letter-spacing: 2px; text-transform: uppercase; text-align: center; background: rgb(136, 189, 67); border-radius: 0px; padding: 18px 35px; font-family: Spartan, sans-serif; font-size: 13px; font-weight: 600; transition: 0.3s; display: inline-block; }.slide-btn:hover { color: rgb(255, 255, 255); background: rgb(0, 0, 0); }.slider-nav { z-index: 10; gap: 10px; display: flex; position: absolute; bottom: 40px; left: 50%; transform: translate(-50%); }.nav-dot { cursor: pointer; background: rgb(184, 205, 217); border: none; width: 32px; height: 4px; transition: 0.3s; }.nav-dot.active { background: rgb(13, 13, 13); }.slider-arrow { cursor: pointer; z-index: 10; background: rgba(255, 255, 255, 0.1); border: none; border-radius: 50%; justify-content: center; align-items: center; width: 50px; height: 50px; transition: 0.3s; display: flex; position: absolute; top: 50%; transform: translateY(-50%); }.slider-arrow:hover { background: rgb(255, 255, 255); }.slider-arrow [class^="main-icon-"] { color: rgb(255, 255, 255); font-size: 30px; }.slider-arrow:hover [class^="main-icon-"] { color: rgb(115, 119, 171); }.slider-arrow.prev { left: 30px; }.slider-arrow.next { right: 30px; }@media (max-width: 1200px) {
  .hero-slider { height: 480px; }
