}.bestseller-section { background: rgb(255, 255, 255); padding: 80px 0px; }.bestseller-header { text-align: center; margin-bottom: 30px; }.bestseller-subtitle { color: rgb(136, 189, 67); letter-spacing: 3px; text-transform: uppercase; margin-bottom: 10px; font-family: Spartan, sans-serif; font-size: 14px; font-weight: 600; display: block; }.bestseller-title { color: rgb(34, 34, 34); margin: 0px; font-family: Reingttoon, "Dancing Script", cursive; font-size: 60px; font-weight: 400; }.bestseller-tabs { justify-content: center; gap: 40px; margin-bottom: 50px; display: flex; }.bestseller-tab { color: rgb(51, 51, 51); cursor: pointer; background: 0px 0px; border: none; padding: 8px 0px; font-family: Spartan, sans-serif; font-size: 14px; font-weight: 500; transition: color 0.2s; position: relative; }.bestseller-tab:hover, .bestseller-tab.active { color: rgb(136, 189, 67); }.bestseller-tab.active::after { content: ""; background: rgb(136, 189, 67); height: 2px; position: absolute; bottom: 0px; left: 0px; right: 0px; }.bestseller-grid { grid-template-columns: repeat(4, 1fr); gap: 30px; display: grid; }.bestseller-product { background: rgb(255, 255, 255); border: 1px solid rgb(238, 238, 238); border-radius: 8px; transition: 0.3s; overflow: hidden; }.bestseller-product:hover { box-shadow: rgba(0, 0, 0, 0.08) 0px 10px 30px; }.product-image-wrap { background: rgb(255, 255, 255); justify-content: center; align-items: center; height: 280px; padding: 30px; transition: background 0.3s; display: flex; position: relative; }.bestseller-product:hover .product-image-wrap { background: rgb(232, 232, 232); }.product-image-wrap img { object-fit: contain; max-width: 100%; max-height: 100%; }.product-actions { opacity: 0; visibility: hidden; gap: 8px; transition: 0.3s; display: flex; position: absolute; bottom: 20px; left: 50%; transform: translate(-50%); }.bestseller-product:hover .product-actions { opacity: 1; visibility: visible; }.action-btn { cursor: pointer; border: none; border-radius: 50%; justify-content: center; align-items: center; width: 45px; height: 45px; transition: 0.3s; display: flex; }.action-btn [class^="main-icon-"] { font-size: 18px; }.cart-btn { color: rgb(255, 255, 255); background: rgb(136, 189, 67); }.cart-btn:hover { background: rgb(122, 168, 58); }.wishlist-btn { color: rgb(51, 51, 51); background: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 8px; }.wishlist-btn:hover { background: rgb(245, 245, 245); }.feature-categories-section { background: rgb(255, 255, 255); padding: 0px 0px 40px; }.veggie-banner { width: 100%; height: 280px; position: relative; overflow: hidden; }.veggie-banner img { object-fit: cover; object-position: center top; width: 100%; height: auto; }.feature-categories-header { text-align: center; margin-bottom: 40px; padding-top: 50px; }.feature-categories-subtitle { color: rgb(51, 51, 51); letter-spacing: 3px; text-transform: uppercase; margin-bottom: 10px; font-family: Spartan, sans-serif; font-size: 14px; font-weight: 600; display: block; }.feature-categories-title { color: rgb(34, 34, 34); margin: 0px; font-family: Reingttoon, "Dancing Script", cursive; font-size: 60px; font-weight: 400; }.feature-categories-grid { flex-wrap: wrap; justify-content: center; gap: 60px; display: flex; }.feature-category-item { opacity: 0; flex-direction: column; align-items: center; text-decoration: none; display: flex; transform: translateY(60px); }.feature-category-item.animate-in { animation: 0.8s cubic-bezier(0.34, 1.56, 0.64, 1) 0s 1 normal forwards running bounceIn; }.feature-category-item.animate-in .feature-category-image { animation: 3s ease-in-out 0s infinite normal none running floatUp; }.feature-category-item:nth-child(2) .feature-category-image, .feature-category-item:nth-child(4) .feature-category-image { animation: 3s ease-in-out 0s infinite normal none running floatDown; }@keyframes bounceIn { 
  0% { opacity: 0; transform: translateY(60px) scale(0.8); }
  50% { transform: translateY(-10px) scale(1.05); }
  70% { transform: translateY(5px) scale(0.98); }
