.rc-dialog { position: relative; width: auto; margin: 10px; }.rc-dialog-wrap { position: fixed; overflow: auto; inset: 0px; z-index: 1050; outline: 0px; }.rc-dialog-title { margin: 0px; font-size: 14px; line-height: 21px; font-weight: bold; }.rc-dialog-content { position: relative; background-color: rgb(255, 255, 255); border: none; border-radius: 6px; background-clip: padding-box; }.rc-dialog-close { cursor: pointer; border: 0px; background: transparent; font-size: 21px; position: absolute; right: 20px; top: 12px; font-weight: 700; line-height: 1; color: rgb(0, 0, 0); text-shadow: rgb(255, 255, 255) 0px 1px 0px; opacity: 0.2; text-decoration: none; }.rc-dialog-close:disabled { pointer-events: none; }.rc-dialog-close-x::after { content: "×"; }.rc-dialog-close:hover { opacity: 1; text-decoration: none; }.rc-dialog-header { padding: 13px 20px 14px; border-radius: 5px 5px 0px 0px; background: rgb(255, 255, 255); color: rgb(102, 102, 102); border-bottom: 1px solid rgb(233, 233, 233); }.rc-dialog-body { padding: 20px; }.rc-dialog-footer { border-top: 1px solid rgb(233, 233, 233); padding: 10px 20px; text-align: right; border-radius: 0px 0px 5px 5px; }.rc-dialog-zoom-enter, .rc-dialog-zoom-appear { opacity: 0; animation-duration: 0.3s; animation-fill-mode: both; animation-timing-function: cubic-bezier(0.08, 0.82, 0.17, 1); animation-play-state: paused; }.rc-dialog-zoom-leave { animation-duration: 0.3s; animation-fill-mode: both; animation-timing-function: cubic-bezier(0.6, 0.04, 0.98, 0.34); animation-play-state: paused; }.rc-dialog-zoom-enter.rc-dialog-zoom-enter-active, .rc-dialog-zoom-appear.rc-dialog-zoom-appear-active { animation-name: rcDialogZoomIn; animation-play-state: running; }.rc-dialog-zoom-leave.rc-dialog-zoom-leave-active { animation-name: rcDialogZoomOut; animation-play-state: running; }@keyframes rcDialogZoomIn { 
